import os
import re
import sys
import glob
import hashlib
from collections import defaultdict, Counter

import kb_lib as K


# =================================================================== 常量

_VALID_TYPE = {"entity", "concept", "source", "topic", "output"}
# canonical 键（规范定义）——**仅用于「近义词提示」**，不作为白名单；
# 白名单由「本库真实键频次」自校准（见 build_known_keys），避免维护一份
# 永远追不上实况的清单（曾因漏列 `pages` 而误报 31 处「拼写错误」）。
_CANON_KEYS = {
    "created", "updated", "type", "tags", "aliases", "summary", "sources",
    "source_reliability", "authors", "authors_source", "corresponding_author",
    "institution", "published", "year", "journal", "source_type", "si_status",
    "evidence_base", "doi", "url", "title", "description", "qc_status",
}
# si_status 合法取值：**收敛到 kb_lib 的唯一一份**（不放宽到无实测支撑的变体）。
# ⚠️ 修订说明：此处原为 `{... , "n/a"}`，注释称"本库实测另有 not_applicable / n/a"。
#    2026-10-10 全库实测：missing 285 ｜ not_applicable 186 ｜ partial 14 ｜ present 9，
#    **`n/a` 为 0 处** —— 即那句"实测另有 n/a"是假的。现只收有证据的 4 个值，
#    并且与 kb_lint.py 共用同一集合，不再各写一份白名单。
_VALID_SI = K.SI_STATUS_VALUES
_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
_FM_KEY_RE = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*)\s*:", re.M)
_BAD_STRUCT_CHARS = ("\\", '"', "\n")


def build_known_keys(pages):
    """自校准白名单：canonical ∪ 本库出现 ≥3 次的键。

    这样 `pages`/`volume`/`source_url` 等**真实在用**的键自动豁免，
    只有**罕见且近似 canonical** 的键才报（即真正的手滑）。
    """
    from collections import Counter
    freq = Counter()
    for _rel, (_fm, _body, fp) in pages.items():
        try:
            fm_raw, _ = K.split_frontmatter(K.read_text(fp))
        except Exception:
            continue
        for line in fm_raw.split("\n"):
            if line and line[0] not in (" ", "\t", "#"):
                m = _FM_KEY_RE.match(line)
                if m:
                    freq[m.group(1)] += 1
    known = set(_CANON_KEYS) | {k for k, v in freq.items() if v >= 3}
    return known


def _iter_fm_keys(fm_raw):
    keys = []
    for line in (fm_raw or "").split("\n"):
        if not line or line[0] in (" ", "\t", "#"):
            continue
        m = _FM_KEY_RE.match(line)
        if m:
            keys.append(m.group(1))
    return keys


def _resolve_vault_file_shared(link_target, vault_root):
    """资源型 wikilink → 真实文件（委托给 kb_lint 的同一实现）。

    🔴 **单一解析器**。2026-10-10 实测：本模块原先自带一个「差不多」的解析器
    （只 `os.path.exists`，不补 `.md`），而 `kb_lint._resolve_vault_file` 会补后缀。
    同一批链接因此得到**互相矛盾的判定**：

        raw/text/2026-EMSeek-electron-microscopy-agentic-platform-SciAdv
          kb_lint_deep（旧） -> 不存在      ← 报 ERROR
          kb_lint（同一个链接） -> ...-SciAdv.md   ← 文件确实在盘上

    结果是全库 deep lint 的 **ERROR 计数 2 条，全部是假阳性**——而它又是唯一
    会报 ERROR 的 frontmatter 回链检查，于是「零缺陷」这个结论完全建立在坏计数器上。
    这正是 CLAUDE.md §已知陷阱 记过的「同一个错误的两个独立实现」形态，
    故此处不再保留第二实现，一律委托。
    """
    try:
        import kb_lint as KL
        got = KL._resolve_vault_file(link_target, vault_root)
        return got if got else None
    except Exception:                                          # noqa: BLE001
        # 兜底：连 kb_lint 都导不进来时，至少补一次 `.md`（这是本模块原先漏掉的那一步）
        t = link_target.replace("\\|", "|").split("|")[0].split("#")[0].strip()
        t = t.replace("\\", "").replace("\\", "/").lstrip("/")
        p = os.path.join(vault_root, t)
        for c in (p, p + ".md"):
            if os.path.exists(c):
                return os.path.relpath(c, vault_root).replace("\\", "/")
        return None


def _resource_exists(link_target, vault_root):
    return _resolve_vault_file_shared(link_target, vault_root) is not None


def _lev(a, b):
    if abs(len(a) - len(b)) > 2:
        return 99
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ca != cb)))
        prev = cur
    return prev[-1]


# =================================================================== A 结构完整性

def check_raw_resource_links(fm, vault_root):
    """A1: sources 字段内的 raw/ 回链是否指向真实文件。

    这些链接在 frontmatter，extract_outlinks 扫不到 body 之外 ⇒ 最易漏检，
    又是 CLAUDE.md 点名的「摄入统计唯一依据」。
    """
    out = []
    srcs = fm.get("sources", [])
    if isinstance(srcs, str):
        srcs = [srcs]
    for s in srcs:
        # ⚠️ 正则要认**转义竖线** `[[raw/x.md\|别名]]`（Markdown 表格单元格内的写法）。
        #    旧写法 `(\|[^\]]*)?` 不认它 ⇒ 目标抓成 `raw/x.md\`（尾部带反斜杠）
        #    ⇒ 必然判「文件不存在」。今天库里 0 处，但这是**潜伏**的假阳性来源，
        #    与 kb_lib.extract_outlinks 的处理方式对齐。
        for m in re.finditer(r"\[\[(raw/[^\]|\\]+?)(?:\\?\|[^\]]*)?\]\]", str(s)):
            tgt = m.group(1)
            if not _resource_exists(tgt, vault_root):
                out.append(("ERROR", "A1-raw-missing",
                            f"sources 字段 raw 回链指向不存在的文件: [[{tgt}]]"))
    return out


def _strip_code(body):
    """剔除 ``` 围栏块与 ` 行内代码。

    CLAUDE.md：代码块内的 [[...]] 是**示例文本，不是链接**——lint 报告里
    演示「坏写法长什么样」会出现假链接，不剔除必误报（第 4 号事故同型）。
    """
    body = re.sub(r"```.*?```", "", body, flags=re.S)
    body = re.sub(r"`[^`\n]*`", "", body)
    return body


def check_image_files(body, vault_root):
    """A2: 嵌入/引用的图片文件是否存在（先剔代码块与示例占位）。"""
    out = []
    b = _strip_code(body)
    for m in re.finditer(r"!{0,3}\[\[([^\]|\n]+?\.(?:png|jpg|jpeg|gif|webp|svg))((?:\\?\|[^\]]*)?)\]\]",
                         b, re.I):
        tgt = m.group(1).strip()
        if tgt.startswith(("http://", "https://")):
            continue
        if "<" in tgt or ">" in tgt:      # 文档里的占位符 `<文件夹>/<图>.png`
            continue
        if not _resource_exists(tgt, vault_root):
            out.append(("ERROR", "A2-img-missing",
                        f"图片链接指向不存在的文件: [[{tgt}]]"))
    return out


def check_fm_key_typos(fm_raw, known_keys):
    """A3: frontmatter 键名拼写（静默丢字段高发处）。

    ⚠️ 判据是「**拼错的键在、正确的键不在**」——这才是「静默丢字段」的真签名。
    仅凭「键名近似」会误报：`teams`（真实字段）/ `pages`（页码）都近似 canonical
    却完全合法，且其所在页的 canonical 键（如 tags）**俱在** ⇒ 不报。
    曾因硬编码白名单漏列 `pages` 而误报 31 处——根因是白名单 ≠ 实况。
    """
    out = []
    keys = set(_iter_fm_keys(fm_raw))
    for k in keys:
        if k in known_keys:
            continue
        best = min(_CANON_KEYS, key=lambda c: _lev(k.lower(), c.lower()))
        if _lev(k.lower(), best.lower()) <= 2 and best not in keys:
            out.append(("WARN", "A3-fm-key-typo",
                        f"frontmatter 疑似拼错字段: `{k}`（是否应为 `{best}`？且 `{best}` 缺失）"))
    return out


def check_date_format(fm):
    out = []
    from datetime import date
    for field in ("created", "updated"):
        v = fm.get(field)
        if v is None:
            continue
        s = str(v).strip().strip('"').strip("'")
        if not _DATE_RE.match(s):
            out.append(("WARN", "A4-date-format", f"{field} 日期格式非 YYYY-MM-DD: {s!r}"))
            continue
        try:
            y, mo, d = (int(x) for x in s.split("-"))
            date(y, mo, d)
        except Exception:
            out.append(("WARN", "A4-date-format", f"{field} 日期非法: {s!r}"))
    return out


# =================================================================== B 字段与证据链

def check_schema_types(fm):
    out = []
    for f in ("tags", "aliases", "sources", "authors"):
        v = fm.get(f)
        if v is not None and not isinstance(v, list):
            out.append(("WARN", "B1-schema-list",
                        f"字段 `{f}` 应为列表，实为 {type(v).__name__}"))
    for f in ("summary", "source_reliability"):
        if isinstance(fm.get(f), list):
            out.append(("WARN", "B1-schema-scalar", f"字段 `{f}` 应为标量，实为列表"))
    return out


def check_authors_struct(fm):
    """B2: authors 三重校验（撇号不算脏值）。"""
    out = []
    au = fm.get("authors")
    if au is None:
        return out
    if isinstance(au, str):
        out.append(("WARN", "B2-authors-str",
                    "authors 为纯字符串，应为列表（对应 qc_fix_authors）"))
    items = au if isinstance(au, list) else [au]
    for it in items:
        s = str(it)
        m = re.fullmatch(r"\[\[(.*?)\]\]", s.strip())
        core = m.group(1) if m else s
        for ch in _BAD_STRUCT_CHARS:
            if ch in core:
                out.append(("WARN", "B2-authors-dirty",
                            f"authors 项含结构破坏字符 {ch!r}: {s[:40]!r}"))
                break
    return out


def check_source_has_raw(fm):
    """source 页必须有**素材出处**。

    🔴 2026-10-11：判据从「必须以 `raw/` 开头」改为「`raw/` 或归档层 `_archive/`」。
    动因：`raw/_park` 解散后，被判跑题/重复而隔离的素材住进了
    `_archive/retired/quarantine/`，于是「素材只在归档层」是**合法**状态。
    旧判据会报 `B4-source-no-raw`（文案："会被误判为未摄入"）——**这句话事实错误**：
    素材在库内、只是不在 `raw/` 下，而"未摄入"的判断依据在别处（摄入统计按 raw/ 回链走）
    会因此**漏掉这几页**。这正是本库记录过的事故型缺省值「库内 = raw/」（§已知陷阱 1b）。
    新判据分三态：`raw/` = 正常；仅 `_archive/` = **WARN**（素材已隔离，
    需人判断该页是否也该一并隔离）；两者皆无 = 仍为 ERROR（真的没有出处）。
    """
    if fm.get("type") != "source":
        return []
    srcs = fm.get("sources", [])
    if isinstance(srcs, str):
        srcs = [srcs]
    joined = "\n".join(str(s) for s in srcs)
    if re.search(r"\[\[raw/", joined):
        return []
    if re.search(r"\[\[_archive/", joined):
        return [("WARN", "B4-source-provenance-archived",
                 "source 页素材仅存于归档层 `_archive/`（已隔离）——素材仍在库内，"
                 "但请确认该页是否也应一并隔离")]
    return [("ERROR", "B4-source-no-raw",
             "source 页 sources 字段无 raw/ 回链（会被误判为未摄入）")]


def check_si_consistency(fm):
    if fm.get("type") != "source":
        return []
    si = fm.get("si_status")
    if si is None:
        return []
    s = str(si).strip().strip('"').strip("'")
    # 带内联注释/说明的取值（如 `missing`（2026-09-24 …））视为合法
    s = re.split(r"[（(`]", s, 1)[0].strip()
    if s and s not in _VALID_SI:
        return [("WARN", "B5-si-value",
                 f"si_status 取值非法: {s!r}（应为 {K.SI_STATUS_HINT}）")]
    return []


def check_evidence_base(fm, ref, sources_meta):
    """B3: concept/topic 的 evidence_base 是否与 sources 重算一致。

    用 qc_evidence_base.classify 的**同一判据**（勿另写「差不多」的规则）。
    """
    if fm.get("type") not in ("concept", "topic"):
        return []
    eb = fm.get("evidence_base")
    if eb is None:
        return [("WARN", "B3-evidence-missing", "concept/topic 页缺 evidence_base")]
    try:
        import qc_evidence_base as QE
    except Exception:
        return []
    srcs = fm.get("sources", [])
    if isinstance(srcs, str):
        srcs = [srcs]
    cited = []
    for s in srcs:
        # ⚠️ 只计**真实的 source 页**：concept 页的 sources 里常混有
        #    [[concepts/...]]（概念互链），若也当成引用会把 strong 算成 mixed
        #    ⇒ 与官方 qc_evidence_base.evidence_for 的过滤口径不一致。
        nm = QE._resolve_source_name(str(s))
        if nm and nm in sources_meta and sources_meta[nm].get("type") == "source":
            cited.append((sources_meta[nm], ""))
    if not cited:
        return []
    expected, _basis = QE.classify(cited)
    if expected != eb:
        return [("WARN", "B3-evidence-stale",
                 f"evidence_base 可能过时：现值 {eb}，按当前 sources 重算为 {expected}")]
    return []


# =================================================================== C 数据质量与冗余

def check_duplicate_aliases(pages):
    amap = defaultdict(set)
    for rel, (fm, _b, _fp) in pages.items():
        al = fm.get("aliases", [])
        if isinstance(al, str):
            al = [al]
        for a in al:
            if a and str(a).strip():
                amap[str(a).strip().lower()].add(os.path.basename(rel).rsplit(".", 1)[0])
    out = []
    for a, names in sorted(amap.items()):
        if len(names) > 1:
            out.append(("_global", "WARN", "C1-dup-alias",
                        f"别名 `{a}` 同时指向 {len(names)} 个页面: {', '.join(sorted(names))}"))
    return out


def check_tag_variants(pages):
    tags = Counter()
    for _rel, (fm, _b, _fp) in pages.items():
        t = fm.get("tags", [])
        if isinstance(t, str):
            t = [t]
        for x in t:
            s = str(x).strip().lower()
            if s:
                tags[s] += 1
    norm = defaultdict(set)
    for t in tags:
        norm[re.sub(r"[-_\s]", "", t)].add(t)
    out = []
    for _key, forms in sorted(norm.items()):
        if len(forms) > 1:
            out.append(("_global", "INFO", "C3-tag-variant",
                        f"tag 疑似拼写变体（建议统一）: {', '.join(sorted(forms))}"))
    return out


def check_same_text_dups(pages):
    """C4: 含相同数字的高相似段（同源副本候选）。只给候选，不改文本。"""
    sig = defaultdict(set)
    for rel, (_fm, body, _fp) in pages.items():
        for para in re.split(r"\n\s*\n", body):
            p = para.strip()
            if len(p) < 60 or p[0] in "#>|-*":
                continue
            if not re.search(r"\d", p):
                continue
            sig[hashlib.md5(re.sub(r"\s+", "", p[:120]).encode()).hexdigest()].add(
                os.path.basename(rel).rsplit(".", 1)[0])
    out = []
    for _k, files in sig.items():
        if len(files) > 1:
            out.append(("_global", "INFO", "C4-same-text",
                        f"疑似同源段（{len(files)} 页含相同数字段，请人工核对）: {', '.join(sorted(files)[:4])}"))
    return out[:30]


# =================================================================== E 工具完整性

def check_tool_integrity(vault_root):
    """E 族：静态可判定的工具健全性。

    ⚠️ **这里只做静态检查**（有无 selftest 字样 / 硬写 .qc/ / 能否 py_compile）。
    「工具**实际能否运行**」需要真跑子进程，代价高（语义检索一次 85s），
    故**不在每次 --deep 内联执行**，而是交给专门工具 `tools/kb_toolcheck.py`
    （实跑 --selftest/--help/写盘防呆，自带 --selftest）。
    E1 的提示信息即指向它——这是 2026-10-06 补上的缺口：此前 E 族只查字符串，
    导致 `kb_semantic_search` 索引陈旧（实跑 FAIL）这类「代码在、功能坏」完全不可见。
    """
    out = []
    tools_dir = os.path.join(vault_root, "tools")
    if not os.path.isdir(tools_dir):
        return out
    for fp in sorted(glob.glob(os.path.join(tools_dir, "kb_*.py")) +
                     glob.glob(os.path.join(tools_dir, "qc_*.py")) +
                     glob.glob(os.path.join(tools_dir, "lit_*.py"))):
        fn = os.path.basename(fp)
        if fn in ("kb_lint.py", "kb_lib.py", "kb_lint_deep.py", "kb_toolcheck.py"):
            continue
        txt = open(fp, encoding="utf-8", errors="replace").read()
        if "selftest" not in txt:
            out.append((f"tools/{fn}", "INFO", "E1-no-selftest",
                        f"{fn} 无 --selftest（CLAUDE.md 要求校验器可自检反算）"))
        # E2 只对 qc_*.py 生效（CLAUDE.md 的规则正是针对 qc 工具）；
        # kb_restructure.py 移动 .qc/ 文档是它的本职，不是硬写输出路径。
        if (fn.startswith("qc_") and re.search(r"""["']\.qc/""", txt)
                and "qc_work_dir" not in txt and "qc_file" not in txt):
            out.append((f"tools/{fn}", "WARN", "E2-hardcoded-qc",
                        f"{fn} 硬写相对路径 .qc/（应用 kb_lib.qc_work_dir）"))
        # E3 编译健全性（快，且能抓真断——语法/导入期错误）
        try:
            import py_compile
            py_compile.compile(fp, doraise=True)
        except Exception as e:  # noqa
            out.append((f"tools/{fn}", "ERROR", "E3-compile-fail",
                        f"{fn} 编译失败: {str(e).splitlines()[0][:80]}"))
    return out


# =================================================================== F 内容严谨性

# ⚠️ 只收**无歧义**的占位记号。`待补`/`待核`/`占位` 在本库是**正当表述**
#    （"仍待补"=数据缺口、"待核查"=方法论要求、"...的一个具体占位"=比喻），
#    首版把它们当占位符 ⇒ 误报 33 处，真值 0。
_PLACEHOLDER_RE = re.compile(r"(TODO|TBD|FIXME|XXX\b|待填写|此处填写|PLACEHOLDER)")


def check_content_rigor(fm, body):
    out = []
    b = _strip_code(body)
    for m in _PLACEHOLDER_RE.finditer(b):
        ln = b[:m.start()].count("\n")
        line = b.split("\n")[ln]
        if line.strip().startswith((">", "#")):
            continue
        out.append(("WARN", "F1-placeholder", f"疑似占位符残留: {m.group(0)}（行 {ln+1}）"))
        break
    if fm.get("type") == "concept":
        pcts = re.findall(r"(?<![\d.])(\d{2,3})%", body)
        if len(pcts) >= 5:
            out.append(("INFO", "F2-pct-dense",
                        f"正文含 {len(pcts)} 处百分比，建议核对是否都带限定词/出处"))
    s = str(fm.get("summary", "") or "").strip().strip('"')
    if s and len(s) < 8:
        out.append(("WARN", "F3-summary-thin", f"summary 过短: {s!r}"))
    return out


# =================================================================== 聚合

_PER_PAGE = [
    ("A1", lambda fm, body, fm_raw, ref, sm: check_raw_resource_links(fm, ref["vault"])),
    ("A2", lambda fm, body, fm_raw, ref, sm: check_image_files(body, ref["vault"])),
    ("A3", lambda fm, body, fm_raw, ref, sm: check_fm_key_typos(fm_raw, ref["known"])),
    ("A4", lambda fm, body, fm_raw, ref, sm: check_date_format(fm)),
    ("B1", lambda fm, body, fm_raw, ref, sm: check_schema_types(fm)),
    ("B2", lambda fm, body, fm_raw, ref, sm: check_authors_struct(fm)),
    ("B3", lambda fm, body, fm_raw, ref, sm: check_evidence_base(fm, ref, sm)),
    ("B4", lambda fm, body, fm_raw, ref, sm: check_source_has_raw(fm)),
    ("B5", lambda fm, body, fm_raw, ref, sm: check_si_consistency(fm)),
    ("F",  lambda fm, body, fm_raw, ref, sm: check_content_rigor(fm, body)),
]

_META_NAMES = {"index", "log", "log_ops", "log_insights"}


def run_deep_extended(pages, vault_root):
    issues = []
    sources_meta = {os.path.basename(r).rsplit(".", 1)[0]: pages[r][0] for r in pages}
    known_keys = build_known_keys(pages)

    for rel in sorted(pages):
        fm, body, fp = pages[rel]
        name = os.path.basename(rel).rsplit(".", 1)[0]
        try:
            fm_raw, _ = K.split_frontmatter(K.read_text(fp))
        except Exception:
            fm_raw = ""
        ref = {"vault": vault_root, "known": known_keys}
        checks = ([("A1", _PER_PAGE[0][1]), ("A2", _PER_PAGE[1][1])]
                  if name in _META_NAMES else _PER_PAGE)
        for _code, fn in checks:
            for lv, code, msg in fn(fm, body, fm_raw, ref, sources_meta):
                issues.append((rel, lv, code, msg, None))

    issues.extend(check_duplicate_aliases(pages))
    issues.extend(check_tag_variants(pages))
    issues.extend(check_same_text_dups(pages))
    issues.extend(check_tool_integrity(vault_root))
    # 归一化为 5 元组，并标注可机械修复项
    norm = []
    for x in issues:
        rec = tuple(x) if len(x) == 5 else (x[0], x[1], x[2], x[3] if len(x) > 3 else "", None)
        norm.append(_tag_fixable(rec))
    return norm


# fix_id → 修复器（在 kb_lint.py 中按 id 分派给 FIXERS）
# ⚠️ 只标注**确实可安全机械修复**的项。tag 变体需选定规范词
#    ⇒ 不自动改，保留给人工（宁可不修，不可改错——本库既有事故皆源于此）。
def _tag_fixable(rec):
    rel, lv, code, msg, _ = rec
    if code in ("B2-authors-str", "B1-schema-list"):
        return (rel, lv, code, msg, "FIX_LIST_WRAP")
    # 日期：仅当**可无损归一化**为 YYYY-MM-DD 时才标（见 fix_date_normalize）
    if code == "A4-date-format":
        return (rel, lv, code, msg, "FIX_DATE")
    return rec


# =================================================================== 修复器

_LIST_FIELDS = ("authors", "tags", "aliases", "sources")


def fix_list_wrap(fm_raw, body, msg):
    """把被写成标量的列表型字段包成列表。

    仅当**恰好一个**目标字段是标量时才动手（多字段时 message 未指明是哪个，
    贸然全改会误伤）——保守为本。
    """
    import re as _re
    m = _re.search(r"字段 `([a-z_]+)` 应为列表", msg) or _re.search(r"`([a-z_]+)` 为纯字符串", msg)
    target = m.group(1) if m else None
    if m and m.group(1) in _LIST_FIELDS:
        fields = [m.group(1)]
    else:
        # authors 为纯字符串
        fields = ["authors"] if "authors" in msg else []

    lines = (fm_raw or "").split("\n")
    changed = False
    for f in fields:
        for i, ln in enumerate(lines):
            mm = _re.match(rf"^{f}\s*:\s*(.+?)\s*$", ln)
            if mm:
                val = mm.group(1).strip()
                if val.startswith("[") or val.startswith("-"):
                    continue
                lines[i:i + 1] = [f + ":", "  - " + val]
                changed = True
                break
    if not changed:
        return None
    return "\n".join(lines), body


_DATE_SEP_RE = re.compile(
    r"^\s*(\d{4})\s*[-/年.]\s*(\d{1,2})\s*[-/月.]\s*(\d{1,2})\s*[日号]?\s*$")


def fix_date_normalize(fm_raw, body, msg):
    """把 `created`/`updated` 的日期归一化为 YYYY-MM-DD。

    **仅在可无损解析时动手**（`2026/1/5`、`2026.1.5`、`2026年1月5日` → `2026-01-05`）；
    语义不明（如 `2026-10`、`最近`）一律返回 None 留给人工。
    合法日期已由 check_date_format 放行，此处只处理被它标记的项。
    """
    import re as _re
    m = _re.search(r"字段 `?([a-z_]+)`?", msg) or _re.search(r"(created|updated)", msg)
    field = m.group(1) if m else None
    if field not in ("created", "updated"):
        return None
    lines = (fm_raw or "").split("\n")
    changed = False
    for i, ln in enumerate(lines):
        mm = _re.match(rf"^{field}\s*:\s*(.+?)\s*$", ln)
        if not mm:
            continue
        val = mm.group(1).strip().strip('"').strip("'")
        dm = _DATE_SEP_RE.match(val)
        if not dm:
            return None  # 无法无损归一化 → 不动
        y, mo, d = dm.group(1), int(dm.group(2)), int(dm.group(3))
        try:
            from datetime import date
            date(int(y), mo, d)
        except Exception:
            return None
        lines[i] = f"{field}: {y}-{mo:02d}-{d:02d}"
        changed = True
        break
    if not changed:
        return None
    return "\n".join(lines), body


FIXERS = {
    "FIX_LIST_WRAP": fix_list_wrap,
    "FIX_DATE": fix_date_normalize,
}


# =================================================================== 自检

def run_selftest():
    """已知答案反算（CLAUDE.md：校验器必须能对样本反算，正反例都要）。"""
    ok = fail = 0
    def chk(name, cond):
        nonlocal ok, fail
        if cond:
            ok += 1
            print(f"  [PASS] {name}")
        else:
            fail += 1
            print(f"  [FAIL] {name}")

    # A3: teams（真实字段，且 tags 俱在）不得报；真拼错（summry 而 summary 缺失）要报
    known = {"tags", "summary", "authors"}
    chk("A3 真实字段 teams 不报（tags 俱在）",
        check_fm_key_typos("tags:\n  - a\nteams:\n  - x", known) == [])
    chk("A3 summry 且 summary 缺失 → 报",
        any(c == "A3-fm-key-typo" for _, c, _ in check_fm_key_typos("summry: x", known)))

    # A2: 代码块内图片示例不得报
    chk("A2 代码块内图片不报",
        check_image_files("```\n[[fig_xyz.png]]\n```", "/nonexist") == [])
    chk("A2 占位符 <文件夹> 不报",
        check_image_files("[[raw/assets/<x>/<y>.png]]", "/nonexist") == [])

    # B5: not_applicable 合法；abc 非法
    chk("B5 not_applicable 合法",
        check_si_consistency({"type": "source", "si_status": "not_applicable"}) == [])
    chk("B5 乱值报错",
        any(c == "B5-si-value" for _, c, _ in
            check_si_consistency({"type": "source", "si_status": "bogus"})))
    # 🆕 2026-10-10 回归夹具：`n/a` **曾经在白名单里但实测 0 处**——
    #    注释声称"本库实测另有 n/a"是假的。现只收有实测支撑的 4 个值；
    #    若将来真的用到 n/a，这里会 FAIL，提醒"先拿证据再放宽白名单"。
    chk("B5 `n/a` 不再被当作合法（无实测支撑，实测 0 处）",
        any(c == "B5-si-value" for _, c, _ in
            check_si_consistency({"type": "source", "si_status": "n/a"})))
    chk("B5 白名单与 kb_lint 共用同一份（kb_lib.SI_STATUS_VALUES）",
        _VALID_SI is K.SI_STATUS_VALUES
        and _VALID_SI == frozenset({"missing", "partial", "present", "not_applicable"}))
    chk("B5 带内联说明的取值仍合法（`missing`（2026-09-24 …））",
        check_si_consistency(
            {"type": "source", "si_status": "missing（2026-09-24 复核）"}) == [])

    # F1: 待补/待核 是正当表述，不报；TODO 报
    chk("F1 待核查不报",
        not any(c == "F1-placeholder" for _, c, _ in check_content_rigor({}, "仍待核查")))
    chk("F1 TODO 报",
        any(c == "F1-placeholder" for _, c, _ in check_content_rigor({}, "TODO 补上")))

    # B2: 撇号不算脏值
    chk("B2 撇号合法",
        check_authors_struct({"authors": ["D'Souza"]}) == [])
    chk("B2 反斜杠脏",
        any(c == "B2-authors-dirty" for _, c, _ in
            check_authors_struct({"authors": ["a\\b"]})))

    # fixer: authors 标量 → 列表
    out = fix_list_wrap("authors: 张三\n", "", "authors 为纯字符串，应为列表")
    chk("fixer authors 标量包列表", out is not None and "  - 张三" in out[0])

    # A4/fixer: 可无损归一的日期 → 改；语义不明 → 不动（反例）
    d = fix_date_normalize("created: 2026/1/5\n", "", "created 日期格式非 YYYY-MM-DD: '2026/1/5'")
    chk("fixer 日期 2026/1/5 → 2026-01-05", d is not None and "created: 2026-01-05" in d[0])
    d2 = fix_date_normalize("created: 2026年10月5日\n", "", "created 日期格式非 YYYY-MM-DD: x")
    chk("fixer 日期 中文年月日 → ISO", d2 is not None and "created: 2026-10-05" in d2[0])
    chk("fixer 日期语义不明(2026-10)不改",
        fix_date_normalize("updated: 2026-10\n", "", "updated 日期格式非 YYYY-MM-DD: x") is None)
    chk("fixer 日期非法(2026-13-01)不改",
        fix_date_normalize("created: 2026/13/1\n", "", "created 日期格式非 YYYY-MM-DD: x") is None)

    # E3: 必须**真的调用** check_tool_integrity，并用一个语法坏文件验证它报错。
    #     ⚠️ 旧夹具写的是
    #         isinstance([x for x in []] if True else check_tool_integrity(...), list)
    #     —— `if True` 让 else 分支**永远不执行**：check_tool_integrity 从没被调用过，
    #        断言退化成 `isinstance([], list)`（恒真）。这是「假自检」的典型：
    #        测试通过不代表功能正常，只代表测试什么都没测。
    import shutil as _sh
    import tempfile as _tf
    probe = ""
    for _base in (_tf.gettempdir(), os.getcwd(), os.path.dirname(os.path.abspath(__file__))):
        _d = os.path.join(_base, "_lint_deep_e3_probe")
        try:
            _sh.rmtree(_d, ignore_errors=True)
            os.makedirs(os.path.join(_d, "tools"), exist_ok=True)
            with open(os.path.join(_d, "tools", "kb_broken.py"), "w",
                      encoding="utf-8") as _f:
                _f.write("def f(:\n")            # 语法坏
            probe = _d
            break
        except OSError:
            continue
    if probe:
        try:
            got = check_tool_integrity(probe)
            chk("E3 语法坏文件真被抓出（夹具真的调用了检查器）",
                any(c == "E3-compile-fail" for _, _, c, _ in got))
        finally:
            _sh.rmtree(probe, ignore_errors=True)
    else:
        chk("E3 无法创建临时夹具（环境受限，跳过）", True)

    # A1: 省略 .md 的 raw 回链**不得**判缺失（2026-10-10 的 2 条假 ERROR 回归夹具）
    _tmpv = None
    try:
        _tmpv = os.path.join(_tf.gettempdir(), "_lint_deep_a1_probe")
        _sh.rmtree(_tmpv, ignore_errors=True)
        os.makedirs(os.path.join(_tmpv, "raw", "text"), exist_ok=True)
        with open(os.path.join(_tmpv, "raw", "text", "x-2026.md"), "w",
                  encoding="utf-8") as _f:
            _f.write("hi")
        chk("A1 省略 .md 的回链不算缺失（补后缀解析）",
            check_raw_resource_links(
                {"sources": ['"[[raw/text/x-2026]]"']}, _tmpv) == [])
        chk("A1 反例 真不存在的回链仍报 ERROR",
            any(c == "A1-raw-missing" for _, c, _ in check_raw_resource_links(
                {"sources": ['"[[raw/text/绝不存在-xyz]]"']}, _tmpv)))
        chk("A1 转义竖线 `\\|` 形式也能解析（不再抓成带反斜杠的目标）",
            check_raw_resource_links(
                {"sources": ['"[[raw/text/x-2026\\|别名]]"']}, _tmpv) == [])
    finally:
        if _tmpv:
            _sh.rmtree(_tmpv, ignore_errors=True)

    # 🔴 2026-10-11：B4 的**三态**判据（正例 + 两个反例）。
    #    动因：`raw/_park` 解散后，"素材只在归档层"成为合法状态，而旧判据把这种情况
    #    报成 ERROR 且文案说"会被误判为未摄入"——**事实错误**（素材在库内）。
    #    三态必须都钉住：raw/ 不报、仅归档报 WARN、都没有才报 ERROR。
    _src_raw = check_source_has_raw(
        {"type": "source", "sources": ['"[[raw/text/a.md]]"']})
    chk("B4 正例 有 raw/ 回链 → 不报", _src_raw == [])
    _src_arch = check_source_has_raw(
        {"type": "source", "sources": ['"[[_archive/retired/quarantine/offtopic/a.md]]"']})
    chk("B4 仅归档层回链 → WARN（素材在库内、已隔离），不再误报 ERROR",
        len(_src_arch) == 1 and _src_arch[0][0] == "WARN"
        and _src_arch[0][1] == "B4-source-provenance-archived")
    _src_none = check_source_has_raw({"type": "source", "sources": ['"[[sources/x.md]]"']})
    chk("B4 反例 两者皆无 → 仍报 ERROR（真的没有出处）",
        len(_src_none) == 1 and _src_none[0][0] == "ERROR"
        and _src_none[0][1] == "B4-source-no-raw")
    chk("B4 非 source 页不参与本判据",
        check_source_has_raw({"type": "concept", "sources": []}) == [])

    print(f"\n{'SELFTEST PASSED' if fail == 0 else 'SELFTEST FAILED'}: {ok}/{ok+fail}")
    return 0 if fail == 0 else 1


# =================================================================== CLI
#
# 🔴 本模块此前**没有 `main()`/argparse/`--help`**，只能由 `kb_lint.py --selftest-deep`
#    代跑，而 `kb_toolcheck.py` 又把 `kb_lint_deep.py` 从名单里排除
#    ⇒ 全库**唯一零自动化门禁的模块**，而且它自己那份 E3 夹具当时是 `if True` 恒真
#    （测试通过不代表功能正常，只代表测试什么都没测）。
#    现在给它一个真入口，便于 kb_toolcheck 直接实跑自检。

def main(argv=None):
    import argparse
    ap = argparse.ArgumentParser(
        prog="kb_lint_deep.py",
        description="kb_lint 的扩展检查族 A–F（**静态、不写盘**；由 kb_lint --deep 调度）")
    ap.add_argument("--selftest", action="store_true", help="已知答案反算（正例+反例）")
    args = ap.parse_args(argv)
    if args.selftest:
        return run_selftest()
    ap.print_help()
    return 0


if __name__ == "__main__":
    try:                                                       # noqa: SIM105
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    except Exception:                                          # noqa: BLE001
        pass
    sys.exit(main())
